// ===== Triage Email =====
// Runs before any AI call. Works out what the email actually says, and whether it is
// a work order at all. Auto-replies and newsletters are rejected here for free.

const CFG = $('Config').first().json;
const out = [];

// ---------- helpers ----------
const S = (v) => (v == null ? '' : String(v));
const squeeze = (s) => S(s).replace(/[ \t\u00a0]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

function pickHeader(j, name) {
  const want = name.toLowerCase();
  const bags = [j.headers, j.header, j.payload && j.payload.headers];
  for (const bag of bags) {
    if (!bag) continue;
    if (Array.isArray(bag)) {                       // [{name,value}] form
      const hit = bag.find((h) => S(h.name).toLowerCase() === want);
      if (hit) return S(hit.value);
    } else if (typeof bag === 'object') {           // {From: "..."} form
      for (const k of Object.keys(bag)) if (k.toLowerCase() === want) return S(bag[k]);
    }
  }
  return '';
}
// The Gmail node's shape changes with the Simplify toggle and across versions,
// so read every field from wherever it happens to live.
function field(j, names, headerName) {
  for (const n of names) {
    const v = n.split('.').reduce((o, k) => (o == null ? o : o[k]), j);
    if (v == null) continue;
    if (typeof v === 'string' && v.trim()) return v;
    if (typeof v === 'object') {
      if (Array.isArray(v.value) && v.value[0]) {   // mailparser: {value:[{address,name}],text}
        const a = v.value[0];
        return a.name ? a.name + ' <' + a.address + '>' : S(a.address);
      }
      if (typeof v.text === 'string' && v.text.trim()) return v.text;
    }
  }
  return headerName ? pickHeader(j, headerName) : '';
}

function htmlToText(html) {
  return S(html)
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(script|style|head)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6]|table)>/gi, '\n')
    .replace(/<li[^>]*>/gi, '\u2022 ')
    .replace(/<td[^>]*>/gi, '\t')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
    .replace(/&#(\d+);/g, (m, d) => { const n = +d; return n > 31 && n < 65536 ? String.fromCharCode(n) : ' '; })
    .replace(/&[a-z]+;/gi, ' ');
}

// Everything below a reply marker is history, not this request.
function stripQuoted(text) {
  const lines = S(text).split(/\r?\n/);
  const markers = [
    /^\s*-{2,}\s*Original Message\s*-{2,}/i,
    /^\s*_{5,}\s*$/,
    /^\s*On .{5,80}\b(wrote|schrieb|a \u00e9crit)\s*:\s*$/i,
    /^\s*From:\s.+\s*$/i,
    /^\s*-{2,}\s*Forwarded message\s*-{2,}/i,
    /^\s*Sent from my (iPhone|iPad|Samsung|Android)/i,
    /^\s*--\s*$/,
  ];
  let cut = lines.length;
  for (let i = 0; i < lines.length; i++) {
    if (markers.some((m) => m.test(lines[i]))) {
      // "From:" only counts as a quote marker once we are past the opening lines
      if (/^\s*From:/i.test(lines[i]) && i < 2) continue;
      cut = i; break;
    }
  }
  let kept = lines.slice(0, cut).filter((l) => !/^\s*>/.test(l));
  while (kept.length && !kept[kept.length - 1].trim()) kept.pop();
  const body = squeeze(kept.join('\n'));
  return body.length >= 20 ? body : squeeze(S(text).replace(/^\s*>.*$/gm, ''));
}

// ---------- the scan ----------
const NOISE_SUBJECT = /(out of office|automatic reply|autoreply|auto-reply|undeliverable|delivery (status notification|has failed)|returned mail|read receipt|^read:|mail delivery (subsystem|failed)|unsubscribe confirmation)/i;
const NOISE_FROM = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounce|newsletter|notifications?@|marketing@)/i;
const WORK_WORDS = /\b(repair|repairs|install(ation|ed)?|service|servicing|maintenance|fault|faulty|broken|leak(ing)?|blocked|replace(ment)?|quote|quotation|estimate|callout|call-out|work order|job|site visit|survey|inspection|boiler|heating|plumb(ing|er)|electric(al|ian)?|hvac|aircon|air con|roof(ing)?|drain|emergency|urgent|asap|po number|purchase order|reference)\b/i;
const FORM_LINE = /^\s*(name|client|customer|company|site|address|postcode|zip|phone|tel|telephone|mobile|email|description|details|issue|problem|work required|scope|priority|urgency|due|required by|po|purchase order|reference|ref)\s*[:\-]\s*\S/im;

function findAll(re, text) { const s = new Set(); let m; const r = new RegExp(re.source, re.flags.includes('g') ? re.flags : re.flags + 'g');
  while ((m = r.exec(text)) !== null) s.add(m[0]); return [...s]; }

for (const item of $input.all()) {
  const j = item.json || {};

  const subject = squeeze(field(j, ['subject', 'Subject'], 'Subject'));
  const from = squeeze(field(j, ['from', 'From'], 'From'));
  const toAddr = squeeze(field(j, ['to', 'To'], 'To'));
  const cc = squeeze(field(j, ['cc', 'Cc'], 'Cc'));
  const date = field(j, ['date', 'Date', 'internalDate'], 'Date');
  const msgId = S(j.id || j.messageId || pickHeader(j, 'Message-ID')) || ('nogid-' + subject.slice(0, 40));
  const threadId = S(j.threadId || '');

  const rawText = field(j, ['text', 'textPlain', 'body.text', 'snippet']);
  const rawHtml = field(j, ['html', 'textHtml', 'body.html']);
  const fullText = squeeze(rawText || htmlToText(rawHtml));
  const bodyForAi = stripQuoted(fullText);

  // attachments: names come from the binary properties the Gmail node created
  const bin = item.binary || {};
  const attachments = Object.keys(bin)
    .filter((k) => /^attachment/i.test(k) || CFG.treat_all_binaries_as_attachments === true)
    .map((k) => ({ key: k, fileName: S(bin[k].fileName) || k, mimeType: S(bin[k].mimeType), size: Number(bin[k].fileSize || 0) || null }))
    .filter((a) => !/^image\/(png|gif)$/i.test(a.mimeType) || a.fileName.length > 12);  // drop tracking pixels / signature logos

  // --- noise gate ---
  const autoSubmitted = pickHeader(j, 'Auto-Submitted');
  const precedence = pickHeader(j, 'Precedence');
  const reasons = [];
  if (autoSubmitted && !/^no$/i.test(autoSubmitted)) reasons.push('AUTO_SUBMITTED');
  if (pickHeader(j, 'X-Autoreply') || pickHeader(j, 'X-Autorespond')) reasons.push('AUTORESPONDER');
  if (/^(bulk|list|auto_reply|junk)$/i.test(precedence)) reasons.push('BULK_PRECEDENCE');
  if (NOISE_SUBJECT.test(subject)) reasons.push('AUTO_SUBJECT');
  if (NOISE_FROM.test(from)) reasons.push('NOREPLY_SENDER');
  if (pickHeader(j, 'List-Unsubscribe') || /\bunsubscribe\b/i.test(fullText.slice(-600))) reasons.push('MARKETING');

  // --- work-order signals ---
  const hay = subject + '\n' + bodyForAi;
  const signals = [];
  if (WORK_WORDS.test(hay)) signals.push('WORK_LANGUAGE');
  if (FORM_LINE.test(bodyForAi)) signals.push('FORM_FIELDS');
  if (attachments.length) signals.push('HAS_ATTACHMENT');
  if (CFG.sender_allowlist) {
    const allow = S(CFG.sender_allowlist).split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
    if (allow.length && allow.some((d) => from.toLowerCase().includes(d))) signals.push('TRUSTED_SENDER');
  }

  const noisy = reasons.length > 0 && !signals.includes('TRUSTED_SENDER');
  const enough = CFG.strict_triage === false ? true : signals.length > 0;
  const isWorkOrder = !noisy && enough && bodyForAi.length >= 15;
  if (!isWorkOrder && !noisy && bodyForAi.length < 15) reasons.push('EMPTY_BODY');
  if (!isWorkOrder && !noisy && !enough) reasons.push('NO_WORK_SIGNALS');

  // a stable reference: the same email always produces the same one
  let h = 0; for (let i = 0; i < msgId.length; i++) { h = ((h << 5) - h + msgId.charCodeAt(i)) | 0; }
  const ref = 'WO-' + Math.abs(h).toString(36).toUpperCase().padStart(6, '0').slice(0, 6);

  // candidates are used later to prove the model did not invent contact details
  const senderEmail = (from.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [''])[0].toLowerCase();
  const candidates = {
    emails: [...new Set(findAll(/[\w.+-]+@[\w-]+\.[\w.-]+/g, hay).map((e) => e.toLowerCase()).concat(senderEmail ? [senderEmail] : []))],
    phones: findAll(/(?:\+?\d[\d\s().-]{7,}\d)/g, hay).map((p) => p.trim()),
    postcodes: findAll(/\b[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}\b/gi, hay).map((p) => p.toUpperCase()),
  };

  out.push({
    json: {
      ref, msgId, threadId, subject, from, senderEmail, to: toAddr, cc, date: S(date),
      bodyForAi: bodyForAi.slice(0, Number(CFG.max_body_chars) || 6000),
      bodyTruncated: bodyForAi.length > (Number(CFG.max_body_chars) || 6000),
      fullText, attachments, candidates,
      isWorkOrder, triageSignals: signals, triageReasons: reasons,
    },
    binary: item.binary,          // carry the original attachments forward
  });
}
return out;

// ===== Validate Extraction =====
// The model reads. This code decides. Nothing reaches Jobber that is not either
// present in the original email or clearly flagged for a human.

const src = $('Triage Email').first().json;
const CFG = $('Config').first().json;
const S = (v) => (v == null ? '' : String(v));
const clip = (s, n) => (S(s).length > n ? S(s).slice(0, n - 1).trim() + '\u2026' : S(s).trim());
const digits = (s) => S(s).replace(/\D/g, '');
const flags = [];

// ---------- 1. get JSON out of the model, whatever it wrapped it in ----------
let raw = $input.first().json;
let ai = raw && raw.message ? raw.message.content : (raw.content !== undefined ? raw.content : raw);
if (typeof ai === 'string') {
  const txt = ai.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  try { ai = JSON.parse(txt); }
  catch (e) {
    const m = txt.match(/\{[\s\S]*\}/);          // a JSON object hiding inside chatter
    if (!m) { ai = {}; flags.push('MODEL_OUTPUT_UNREADABLE'); }
    else {
      try { ai = JSON.parse(m[0]); flags.push('MODEL_OUTPUT_REPAIRED'); }
      catch (e2) { ai = {}; flags.push('MODEL_OUTPUT_UNREADABLE'); }
    }
  }
}
if (!ai || typeof ai !== 'object' || Array.isArray(ai)) { ai = {}; flags.push('MODEL_OUTPUT_UNREADABLE'); }

const hay = (src.subject + '\n' + src.bodyForAi).toLowerCase();

// ---------- 2. title ----------
let title = clip(ai.title, 100);
if (!title) { title = clip(src.subject || 'Work order from ' + src.from, 100); flags.push('TITLE_FROM_SUBJECT'); }

// ---------- 3. who the client is ----------
let company = clip(ai.client_company, 100);
let person = clip(ai.client_name, 100);
if (!person) {                       // a company name is not a contact name
  const nameFromHeader = (src.from.match(/^\s*"?([^"<]+?)"?\s*</) || [, ''])[1].trim();
  person = clip(nameFromHeader, 100);
  if (person) flags.push('CLIENT_NAME_FROM_SENDER');
}
// Jobber rejects a client with no last name, so always produce one.
let firstName = '', lastName = '';
if (person) {
  const parts = person.replace(/\s+/g, ' ').trim().split(' ');
  if (parts.length === 1) { lastName = parts[0]; }
  else { firstName = parts.slice(0, -1).join(' '); lastName = parts[parts.length - 1]; }
}
if (!lastName) {
  lastName = company || clip(src.senderEmail.split('@')[0] || 'Unknown', 60);
  flags.push('CLIENT_LAST_NAME_SUBSTITUTED');
}
// a person the email never mentions is a made-up person
const whoHay = (src.subject + '\n' + src.bodyForAi + '\n' + src.from).toLowerCase();
const nameParts = [firstName, lastName].filter((p) => p && p.length > 2).map((p) => p.toLowerCase());
if (nameParts.length && !nameParts.some((p) => whoHay.includes(p))) flags.push('CLIENT_NAME_NOT_IN_EMAIL');

// ---------- 4. contact details must actually appear in the email ----------
let email = S(ai.client_email).trim().toLowerCase();
if (email) {
  const known = (src.candidates.emails || []).map((e) => e.toLowerCase());
  if (!known.includes(email)) { flags.push('EMAIL_NOT_IN_EMAIL_BODY'); email = ''; }
}
if (!email && src.senderEmail) { email = src.senderEmail; flags.push('EMAIL_FROM_SENDER'); }

let phone = S(ai.client_phone).trim();
if (phone) {
  const want = digits(phone);
  const known = (src.candidates.phones || []).map(digits);
  const ok = want.length >= 7 && known.some((k) => k === want || k.endsWith(want.slice(-9)) || want.endsWith(k.slice(-9)));
  if (!ok) { flags.push('PHONE_NOT_IN_EMAIL_BODY'); phone = ''; }
}

// ---------- 5. address ----------
let address = clip(ai.site_address, 200);
if (address) {
  const pc = (address.match(/\b[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}\b/i) || [''])[0].toUpperCase().replace(/\s/g, '');
  const knownPc = (src.candidates.postcodes || []).map((p) => p.replace(/\s/g, ''));
  const words = address.toLowerCase().split(/[\s,]+/).filter((w) => w.length > 3);
  const overlap = words.filter((w) => hay.includes(w)).length;
  // a postcode the email never contains is invented, whether or not the email had one
  if (pc && !knownPc.includes(pc)) { flags.push('POSTCODE_NOT_IN_EMAIL_BODY'); address = ''; }
  else if (!overlap && words.length) { flags.push('ADDRESS_NOT_IN_EMAIL_BODY'); address = ''; }
}
if (!address) flags.push('NO_SITE_ADDRESS');

// ---------- 6. the work itself ----------
let overview = clip(ai.work_overview, 2000);
if (!overview || overview.length < 15) {
  overview = clip(src.bodyForAi, 2000);
  flags.push('OVERVIEW_FROM_RAW_EMAIL');
}

const URGENCY = ['emergency', 'urgent', 'normal', 'low'];
let urgency = S(ai.urgency).toLowerCase().trim();
if (!URGENCY.includes(urgency)) { urgency = /\b(emergency|asap|immediately|urgent)\b/i.test(hay) ? 'urgent' : 'normal'; }

// ---------- 7. requested date ----------
let requested = null;
if (ai.requested_date) {
  const d = new Date(S(ai.requested_date).length <= 10 ? S(ai.requested_date) + 'T09:00:00Z' : S(ai.requested_date));
  const days = (d - new Date()) / 86400000;
  if (!isNaN(d.getTime()) && days > -2 && days < 366) requested = d.toISOString().slice(0, 10);
  else flags.push('REQUESTED_DATE_IMPLAUSIBLE');
}

// ---------- 8. verdict ----------
const hard = ['MODEL_OUTPUT_UNREADABLE', 'EMAIL_NOT_IN_EMAIL_BODY', 'PHONE_NOT_IN_EMAIL_BODY',
              'POSTCODE_NOT_IN_EMAIL_BODY', 'ADDRESS_NOT_IN_EMAIL_BODY', 'OVERVIEW_FROM_RAW_EMAIL',
              'CLIENT_LAST_NAME_SUBSTITUTED', 'CLIENT_NAME_NOT_IN_EMAIL'];
const needsReview = flags.some((f) => hard.includes(f)) || (!address && urgency === 'emergency') || src.bodyTruncated;
if (src.bodyTruncated) flags.push('EMAIL_TRUNCATED_FOR_MODEL');

return [{
  json: {
    ...src,
    extracted: {
      title, firstName, lastName, company, email, phone, address,
      overview, urgency, requestedDate: requested,
      modelNotes: clip(ai.notes, 300),
    },
    flags, needsReview,
    status: needsReview ? 'NEEDS_REVIEW' : 'AUTO_OK',
  },
  binary: $('Triage Email').first().binary,
}];

// ===== Build PDF + Split Files =====
// Writes a real PDF with no library, because an n8n Code node cannot install one.
// Then emits one item per file (the snapshot first, then the original attachments)
// so the Drive node can upload them one at a time.

const v = $('Validate Extraction').first().json;
const srcBinary = $('Triage Email').first().binary || {};
const folder = $input.first().json || {};
const CFG = $('Config').first().json;
const e = v.extracted;

// ---------------- PDF writer ----------------
const PAGE_W = 595, PAGE_H = 842, MARGIN = 50;
const BODY_SIZE = 9, BODY_LEAD = 12;
const COURIER_W = 0.6;                                   // Courier is monospaced: exact wrapping
const MAX_CHARS = Math.floor((PAGE_W - MARGIN * 2) / (BODY_SIZE * COURIER_W));   // 91
const WIN = { 0x2018: 0x91, 0x2019: 0x92, 0x201c: 0x93, 0x201d: 0x94, 0x2013: 0x96,
              0x2014: 0x97, 0x2022: 0x95, 0x20ac: 0x80, 0x2026: 0x85, 0x2122: 0x99 };

function toWinAnsi(s) {
  let out = '';
  for (const ch of String(s == null ? '' : s)) {
    const c = ch.codePointAt(0);
    if (c === 9) { out += '    '; continue; }
    if (c < 32) continue;
    if (c < 256) { out += ch; continue; }
    out += WIN[c] !== undefined ? String.fromCharCode(WIN[c]) : '?';
  }
  return out;
}
const esc = (s) => toWinAnsi(s).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');

function wrap(text, width) {
  const lines = [];
  for (const para of String(text == null ? '' : text).split(/\r?\n/)) {
    if (!para.trim()) { lines.push(''); continue; }
    let line = '';
    for (const word of para.split(/\s+/)) {
      if (word.length > width) {                          // a URL or a long token
        if (line) { lines.push(line); line = ''; }
        for (let i = 0; i < word.length; i += width) lines.push(word.slice(i, i + width));
        continue;
      }
      if (!line) line = word;
      else if ((line + ' ' + word).length <= width) line += ' ' + word;
      else { lines.push(line); line = word; }
    }
    if (line) lines.push(line);
  }
  return lines;
}

// A document is a flat list of drawing instructions; pagination happens afterwards.
const doc = [];
const push = (font, size, text, lead, gap) => doc.push({ font, size, text: String(text == null ? '' : text), lead: lead || BODY_LEAD, gap: gap || 0 });
const rule = () => doc.push({ rule: true, lead: 8, gap: 4 });
const heading = (t) => { doc.push({ font: 'F2', size: 11, text: t, lead: 15, gap: 10 }); rule(); };
const kv = (label, value) => {
  if (value === null || value === undefined || value === '') return;
  const lines = wrap(String(value), MAX_CHARS - 20);
  push('F2', BODY_SIZE, label, BODY_LEAD);
  doc[doc.length - 1].inlineValue = lines[0] || '';
  for (let i = 1; i < lines.length; i++) push('F3', BODY_SIZE, '                    ' + lines[i], BODY_LEAD);
};

const nowIso = new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC';
for (const l of wrap(v.ref + '  ' + e.title, 46)) push('F2', 15, l, 19);
push('F1', 9, 'Snapshot taken ' + nowIso + ' \u00b7 ' + (v.status === 'AUTO_OK' ? 'Extracted automatically' : 'FLAGGED FOR REVIEW'), 14, 2);
rule();

heading('WORK ORDER');
kv('Client', [e.firstName, e.lastName].filter(Boolean).join(' '));
kv('Company', e.company);
kv('Email', e.email);
kv('Phone', e.phone);
kv('Site address', e.address);
kv('Urgency', e.urgency.toUpperCase());
kv('Requested date', e.requestedDate);
kv('Checks', v.flags.length ? v.flags.join(', ') : 'none raised');

heading('WORK OVERVIEW');
for (const l of wrap(e.overview, MAX_CHARS)) push('F3', BODY_SIZE, l);

heading('ORIGINAL EMAIL');
kv('From', v.from);
kv('To', v.to);
kv('Cc', v.cc);
kv('Date', v.date);
kv('Subject', v.subject);
kv('Gmail id', v.msgId);
const names = (v.attachments || []).map((a) => a.fileName);
kv('Attachments', names.length ? names.join(', ') : 'none');
push('F1', 9, '', 8);
for (const l of wrap(v.fullText || '(no readable body)', MAX_CHARS)) push('F3', BODY_SIZE, l);

// ---------------- paginate ----------------
const TOP = PAGE_H - MARGIN, BOTTOM = MARGIN + 24;
const pages = []; let cur = []; let y = TOP;
for (const op of doc) {
  const need = (op.gap || 0) + (op.lead || BODY_LEAD);
  if (y - need < BOTTOM) { pages.push(cur); cur = []; y = TOP; }
  y -= (op.gap || 0);
  cur.push({ ...op, y: y });
  y -= (op.lead || BODY_LEAD);
}
pages.push(cur);

// ---------------- emit ----------------
function contentFor(ops, pageNo, total) {
  let s = '';
  for (const op of ops) {
    if (op.rule) { s += '0.75 w 0.6 G ' + MARGIN + ' ' + op.y.toFixed(2) + ' m ' + (PAGE_W - MARGIN) + ' ' + op.y.toFixed(2) + ' l S 0 G\n'; continue; }
    if (op.text !== '') s += 'BT /' + op.font + ' ' + op.size + ' Tf ' + MARGIN + ' ' + op.y.toFixed(2) + ' Td (' + esc(op.text) + ') Tj ET\n';
    if (op.inlineValue) s += 'BT /F3 ' + op.size + ' Tf ' + (MARGIN + 110) + ' ' + op.y.toFixed(2) + ' Td (' + esc(op.inlineValue) + ') Tj ET\n';
  }
  s += 'BT /F1 8 Tf ' + MARGIN + ' ' + (MARGIN - 6) + ' Td (' + esc(v.ref + '  \u00b7  page ' + pageNo + ' of ' + total) + ') Tj ET\n';
  return s;
}

const objs = [];
objs[1] = '<< /Type /Catalog /Pages 2 0 R >>';
const firstPageObj = 6;
const kids = pages.map((_, i) => (firstPageObj + i * 2) + ' 0 R').join(' ');
objs[2] = '<< /Type /Pages /Kids [' + kids + '] /Count ' + pages.length + ' >>';
objs[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
objs[4] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
objs[5] = '<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>';
pages.forEach((ops, i) => {
  const pageNum = firstPageObj + i * 2, contentNum = pageNum + 1;
  objs[pageNum] = '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + PAGE_W + ' ' + PAGE_H + ']'
    + ' /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >> >> /Contents ' + contentNum + ' 0 R >>';
  const stream = contentFor(ops, i + 1, pages.length);
  objs[contentNum] = '<< /Length ' + Buffer.byteLength(stream, 'latin1') + ' >>\nstream\n' + stream + 'endstream';
});

let pdf = '%PDF-1.4\n%\xe2\xe3\xcf\xd3\n';
const offsets = [];
for (let i = 1; i < objs.length; i++) {
  offsets[i] = Buffer.byteLength(pdf, 'latin1');
  pdf += i + ' 0 obj\n' + objs[i] + '\nendobj\n';
}
const xrefAt = Buffer.byteLength(pdf, 'latin1');
pdf += 'xref\n0 ' + objs.length + '\n0000000000 65535 f \n';
for (let i = 1; i < objs.length; i++) pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
pdf += 'trailer\n<< /Size ' + objs.length + ' /Root 1 0 R >>\nstartxref\n' + xrefAt + '\n%%EOF\n';

// ---------------- files out ----------------
const safe = (n) => String(n || 'file').replace(/[\\/:*?"<>|\u0000-\u001f]/g, '_').replace(/\s+/g, ' ').trim().slice(0, 90) || 'file';
const folderId = folder.id || CFG.drive_parent_folder_id;
const folderLink = folder.id ? 'https://drive.google.com/drive/folders/' + folder.id : '';
const common = { ref: v.ref, folderId, folderLink, needsReview: v.needsReview };

const out = [{
  json: { ...common, fileName: v.ref + ' email snapshot.pdf', kind: 'snapshot', pages: pages.length },
  binary: { data: { data: Buffer.from(pdf, 'latin1').toString('base64'),
    mimeType: 'application/pdf', fileName: v.ref + ' email snapshot.pdf', fileExtension: 'pdf' } },
}];

(v.attachments || []).forEach((a, i) => {
  const b = srcBinary[a.key];
  if (!b || !b.data) return;
  const name = v.ref + ' ' + safe(a.fileName);
  out.push({ json: { ...common, fileName: name, kind: 'attachment', index: i },
             binary: { data: { ...b, fileName: name } } });
});

return out;

// ===== Build Jobber Documents =====
// Turns the checked extraction into (a) a client search and (b) a client create,
// plus the instructions text the office will actually read in Jobber.

const v = $('Validate Extraction').first().json;
const CFG = $('Config').first().json;
const files = ($input.first().json.files || []).filter(Boolean);
const e = v.extracted;

// --- GraphQL literal writer -------------------------------------------------
// Values are written as literals, never concatenated as raw text. Strings go
// through JSON.stringify, whose escaping rules match GraphQL's, so a client
// called  Bob") { x } #  lands in Jobber as that exact name instead of
// rewriting the query.
function gql(v) {
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'null';
  if (Array.isArray(v)) return '[' + v.map(gql).join(', ') + ']';
  if (typeof v === 'object') {
    if (v.__enum !== undefined) return String(v.__enum).replace(/[^A-Za-z0-9_]/g, '');
    const keys = Object.keys(v).filter((k) => v[k] !== undefined && v[k] !== null && v[k] !== '');
    return '{' + keys.map((k) => k.replace(/[^A-Za-z0-9_]/g, '') + ': ' + gql(v[k])).join(', ') + '}';
  }
  return JSON.stringify(String(v));
}

const S = (v2) => (v2 == null ? '' : String(v2));
// Drive replaces the item with its own response, so the folder link comes from the
// node that built it, and each file's kind is read back off its name.
const folderLink = S($('Build PDF + Split Files').first().json.folderLink);
const named = files.map((f) => {
  const name = S(f.name || f.fileName);
  return { id: S(f.id), name, kind: /snapshot/i.test(name) ? 'snapshot' : 'attachment' };
});
const snapshot = named.find((f) => f.kind === 'snapshot');
const fileLines = named.map((f) => '  - ' + f.name + (f.id ? '  https://drive.google.com/file/d/' + f.id + '/view' : ''));

// ---------- what a human sees inside Jobber ----------
const instructions = [
  e.overview,
  '',
  '--- intake details ---',
  'Reference: ' + v.ref,
  'Urgency: ' + e.urgency.toUpperCase(),
  e.requestedDate ? 'Requested date: ' + e.requestedDate : '',
  e.address ? 'Site address: ' + e.address : 'Site address: NOT GIVEN IN EMAIL',
  'From: ' + v.from,
  'Received: ' + (v.date || 'unknown'),
  'Subject: ' + v.subject,
  folderLink ? 'Original email + attachments: ' + folderLink : '',
  fileLines.length ? 'Files:' : '',
  ...fileLines,
  v.flags.length ? 'Automatic checks raised: ' + v.flags.join(', ') : 'Automatic checks: none raised',
].filter((l) => l !== '').join('\n').slice(0, 8000);

// ---------- client search ----------
const searchTerm = e.email || [e.firstName, e.lastName].filter(Boolean).join(' ') || e.company;
const findQuery = 'query FindClient {\n'
  + '  clients(first: 5, searchTerm: ' + gql(searchTerm) + ') {\n'
  + '    totalCount\n'
  + '    nodes { id firstName lastName companyName jobberWebUri emails { address } }\n'
  + '  }\n}';

// ---------- client create (used only if the search finds nobody) ----------
const postcode = (e.address.match(/\b[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}\b/i) || [''])[0];
const street = e.address.replace(postcode, '').replace(/[,\s]+$/, '').trim();
const clientInput = {
  firstName: e.firstName,
  lastName: e.lastName,
  companyName: e.company,
  emails: e.email ? [{ description: { __enum: 'MAIN' }, primary: true, address: e.email }] : undefined,
  phones: e.phone ? [{ description: { __enum: 'MAIN' }, primary: true, number: e.phone }] : undefined,
  billingAddress: (CFG.set_billing_address !== false && e.address)
    ? { street1: street.slice(0, 120), postalCode: postcode || undefined } : undefined,
};
const createClientQuery = 'mutation CreateClient {\n'
  + '  clientCreate(input: ' + gql(clientInput) + ') {\n'
  + '    client { id firstName lastName companyName jobberWebUri }\n'
  + '    userErrors { message path }\n'
  + '  }\n}';

return [{
  json: {
    ...v,
    files: named,
    folderLink,
    snapshotLink: snapshot && snapshot.id ? 'https://drive.google.com/file/d/' + snapshot.id + '/view' : '',
    instructions,
    searchTerm,
    findBody: { query: findQuery },
    createClientBody: { query: createClientQuery },
  },
}];

// ===== Choose Client =====
// Reads the search result. Jobber returns HTTP 200 even when it refuses the query,
// so top-level errors are checked here rather than trusted.
const ctx = $('Build Jobber Documents').first().json;
const res = $input.first().json || {};
const flags = [...(ctx.flags || [])];
const S = (v) => (v == null ? '' : String(v));

let clientId = '';
let clientName = '';
let clientWebUri = '';
let searchWorked = true;

if (Array.isArray(res.errors) && res.errors.length) {
  searchWorked = false;
  const msg = S(res.errors[0].message);
  // e.g. the searchTerm argument not existing on this API version
  flags.push(/argument|field|unknown/i.test(msg) ? 'CLIENT_SEARCH_UNSUPPORTED' : 'CLIENT_SEARCH_FAILED');
} else {
  const nodes = ((res.data || {}).clients || {}).nodes || [];
  const wantEmail = S(ctx.extracted.email).toLowerCase();
  const wantName = [ctx.extracted.firstName, ctx.extracted.lastName].filter(Boolean).join(' ').toLowerCase();
  const wantCompany = S(ctx.extracted.company).toLowerCase();

  const byEmail = wantEmail && nodes.find((n) => (n.emails || []).some((x) => S(x.address).toLowerCase() === wantEmail));
  const byName = !byEmail && wantName && nodes.find((n) => [n.firstName, n.lastName].filter(Boolean).join(' ').toLowerCase() === wantName);
  const byCompany = !byEmail && !byName && wantCompany && nodes.find((n) => S(n.companyName).toLowerCase() === wantCompany);
  const hit = byEmail || byName || byCompany;

  if (hit) {
    clientId = S(hit.id);
    clientName = [hit.firstName, hit.lastName].filter(Boolean).join(' ') || S(hit.companyName);
    clientWebUri = S(hit.jobberWebUri);
    if (!byEmail) flags.push('CLIENT_MATCHED_ON_NAME_ONLY');   // a human should confirm this is the same person
  } else if (nodes.length) {
    flags.push('SIMILAR_CLIENTS_EXIST');                        // search found people, none of them a confident match
  }
}

return [{
  json: {
    ...ctx,
    clientId, clientName, clientWebUri,
    clientFound: !!clientId,
    searchWorked,
    flags,
    needsReview: ctx.needsReview || flags.includes('CLIENT_MATCHED_ON_NAME_ONLY')
      || flags.includes('SIMILAR_CLIENTS_EXIST') || !searchWorked,
  },
}];

// ===== Build Request Document =====
// Reached from both branches: the client was already in Jobber, or we just created one.
const ctx = $('Choose Client').first().json;
const inbound = $input.first().json || {};
const flags = [...(ctx.flags || [])];

// --- GraphQL literal writer -------------------------------------------------
// Values are written as literals, never concatenated as raw text. Strings go
// through JSON.stringify, whose escaping rules match GraphQL's, so a client
// called  Bob") { x } #  lands in Jobber as that exact name instead of
// rewriting the query.
function gql(v) {
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'null';
  if (Array.isArray(v)) return '[' + v.map(gql).join(', ') + ']';
  if (typeof v === 'object') {
    if (v.__enum !== undefined) return String(v.__enum).replace(/[^A-Za-z0-9_]/g, '');
    const keys = Object.keys(v).filter((k) => v[k] !== undefined && v[k] !== null && v[k] !== '');
    return '{' + keys.map((k) => k.replace(/[^A-Za-z0-9_]/g, '') + ': ' + gql(v[k])).join(', ') + '}';
  }
  return JSON.stringify(String(v));
}

const S = (v) => (v == null ? '' : String(v));
// If the client step failed there is nothing to create, but the HTTP node still runs.
// Sending the cheapest possible query keeps the run alive so Check Result can report
// the real reason instead of n8n throwing on an empty body.
const NOOP = { query: 'query NoOp { account { id } }' };
let clientId = S(ctx.clientId);
let clientName = S(ctx.clientName);
let clientWebUri = S(ctx.clientWebUri);
let created = false;

if (!clientId) {                                   // we came through clientCreate
  const payload = ((inbound.data || {}).clientCreate) || {};
  const userErrors = payload.userErrors || [];
  if (Array.isArray(inbound.errors) && inbound.errors.length) {
    return [{ json: { ...ctx, flags: [...flags, 'CLIENT_CREATE_REJECTED'], needsReview: true,
      fatal: 'clientCreate: ' + S(inbound.errors[0].message), requestBody: NOOP } }];
  }
  if (userErrors.length) {
    return [{ json: { ...ctx, flags: [...flags, 'CLIENT_CREATE_REJECTED'], needsReview: true,
      fatal: 'clientCreate: ' + userErrors.map((u) => S(u.message) + ' (' + (u.path || []).join('.') + ')').join('; '), requestBody: NOOP } }];
  }
  const c = payload.client || {};
  clientId = S(c.id);
  clientName = [c.firstName, c.lastName].filter(Boolean).join(' ') || S(c.companyName);
  clientWebUri = S(c.jobberWebUri);
  created = true;
  if (!clientId) {
    return [{ json: { ...ctx, flags: [...flags, 'CLIENT_CREATE_EMPTY'], needsReview: true,
      fatal: 'clientCreate returned no client id', requestBody: NOOP } }];
  }
}

const input = {
  clientId,
  title: ctx.extracted.title,
  assessment: { instructions: ctx.instructions },
};
const query = 'mutation CreateRequest {\n'
  + '  requestCreate(input: ' + gql(input) + ') {\n'
  + '    request { id title }\n'
  + '    userErrors { message path }\n'
  + '  }\n}';

return [{ json: { ...ctx, clientId, clientName, clientWebUri, clientCreated: created, flags,
  requestBody: { query }, fatal: '' } }];

// ===== Check Result =====
// Jobber answers 200 even when it refuses the work, so success is proved here,
// not assumed. Everything downstream (the log row, the label, the alert) is decided
// from this one node.
const ctx = $('Build Request Document').first().json;
const CFG = $('Config').first().json;
const res = $input.first().json || {};
const S = (v) => (v == null ? '' : String(v));
const flags = [...(ctx.flags || [])];

let requestId = ''; let problem = S(ctx.fatal);

if (!problem) {
  if (Array.isArray(res.errors) && res.errors.length) {
    problem = 'requestCreate: ' + res.errors.map((e) => S(e.message)).join('; ');
    flags.push('JOBBER_REJECTED_QUERY');
  } else {
    const payload = ((res.data || {}).requestCreate) || {};
    const userErrors = payload.userErrors || [];
    if (userErrors.length) {
      problem = 'requestCreate: ' + userErrors.map((u) => S(u.message) + ' (' + (u.path || []).join('.') + ')').join('; ');
      flags.push('JOBBER_REJECTED_REQUEST');
    } else if (payload.request && payload.request.id) {
      requestId = S(payload.request.id);
    } else {
      problem = 'requestCreate returned no request';
      flags.push('JOBBER_EMPTY_RESPONSE');
    }
  }
}

const ok = !problem && !!requestId;
const status = !ok ? 'FAILED' : (ctx.needsReview || flags.length ? 'NEEDS_REVIEW' : 'AUTO_OK');
const cost = ((res.extensions || {}).cost || {});
const e = ctx.extracted || {};

const alert = [
  status === 'FAILED' ? 'WORK ORDER FAILED' : 'Work order needs a look',
  ctx.ref + ' \u00b7 ' + S(e.title),
  'Client: ' + (S(ctx.clientName) || S(e.lastName)) + (ctx.clientCreated ? ' (new in Jobber)' : ''),
  e.urgency && e.urgency !== 'normal' ? 'Urgency: ' + S(e.urgency).toUpperCase() : '',
  problem ? 'Problem: ' + problem : 'Checks: ' + flags.join(', '),
  ctx.folderLink ? ctx.folderLink : '',
].filter(Boolean).join('\n').slice(0, 900);

// one flat row for the sheet, in a fixed column order
const row = {
  logged_at: new Date().toISOString(),
  ref: ctx.ref,
  status,
  title: S(e.title),
  client: S(ctx.clientName) || [e.firstName, e.lastName].filter(Boolean).join(' '),
  company: S(e.company),
  email: S(e.email),
  phone: S(e.phone),
  site_address: S(e.address),
  urgency: S(e.urgency),
  requested_date: S(e.requestedDate),
  from: S(ctx.from),
  subject: S(ctx.subject),
  gmail_id: S(ctx.msgId),
  jobber_request_id: requestId,
  jobber_client_id: S(ctx.clientId),
  drive_folder: S(ctx.folderLink),
  snapshot_pdf: S(ctx.snapshotLink),
  attachments: (ctx.files || []).filter((f) => f.kind === 'attachment').length,
  flags: flags.join('|'),
  problem: problem,
};

// The row sits at the top level so the Sheets node can map it straight onto the
// header row; everything else the later nodes need rides alongside it.
return [{
  json: {
    ...row,
    ok,
    threadId: ctx.threadId,
    msgId: ctx.msgId,
    labelIds: [ok && status === 'AUTO_OK' ? S(CFG.label_processed) : S(CFG.label_review)].filter(Boolean),
    jobber: { requestId, clientId: S(ctx.clientId), clientName: S(ctx.clientName),
              clientCreated: !!ctx.clientCreated, clientWebUri: S(ctx.clientWebUri),
              queryCost: cost.actualQueryCost || null, budgetLeft: (cost.throttleStatus || {}).currentlyAvailable || null },
    alert,
    needsAlert: !ok || status === 'NEEDS_REVIEW',
    flagList: flags,
    row,
  },
}];
